    CALCULATE(count('Recetas Vigentes'[RUN]),
        FILTER(
            'Recetas Vigentes',
            'Recetas Vigentes'[RUN]='Ferrada'[RUN] &&
            CONTAINSSTRING('Recetas Vigentes'[DESCRIPCION ARTICULO],"diazepam"
            )
        )
    ),"SI","NO"
)

